sys_script_include.script:
var OrchestrationService = Class.create();
OrchestrationService.prototype = {

    initialize: function () {
        // All module case tables extend Task: standard task states
        // (-5 Pending = dormant, 2 Work in Progress = active,
        //  3 Closed Complete, 7 Closed Skipped = cancelled).
        this.STATE = {
            inactive:  '-5',
            active:    '2',
            complete:  '3',
            cancelled: '7'
        };
        this.LOG = '[Orchestration] ';
        this.plan = new ModulePlanService();
    },

    /**
     * Submission created: create every planned module case, the first run
     * group active and the rest dormant, then start the first group's
     * playbooks.
     *
     * Which modules, in what order, and what runs in parallel all come from
     * ModulePlanService - this service no longer parses the licence property
     * and no longer holds a module-to-table map.
     *
     * @param submissionId sys_id of the new submission
     * @return Array of module codes created
     */
    kickoff: function (submissionId) {
        var groups = this.plan.groupsFor(submissionId);
        if (!groups.length) {
            gs.warn(this.LOG + 'no module plan resolved for submission ' + submissionId
                + ' - nothing created');
            return [];
        }

        var created = [];
        for (var g = 0; g < groups.length; g++) {
            var first = (g === 0);
            for (var i = 0; i < groups[g].modules.length; i++) {
                var code = groups[g].modules[i].module;
                var caseId = this._createCase(code, submissionId, groups[g].order, first);
                if (caseId) {
                    created.push(code);
                    if (first)
                        this._startPlaybook(code, caseId);
                }
            }
        }

        gs.info(this.LOG + 'kickoff for ' + submissionId + ' created ' + created.length
            + ' cases in ' + groups.length + ' run group(s)');
        return created;
    },

    /**
     * A module case reached Closed Complete: if every parallel sibling in its
     * run group is finished, activate the next group. When the last group
     * finishes, close the journey.
     *
     * @param completedModuleCode registry code ('clearance') or licence code
     *        ('SUBMISSION_CLEARANCE') - both resolve
     * @param submissionId sys_id of the parent submission
     * @return Array of module codes activated for the next group
     */
    advance: function (completedModuleCode, submissionId) {
        var next = this.plan.nextGroup(completedModuleCode, submissionId);

        if (!next.length) {
            // Either a sibling is still outstanding, or that was the last group.
            if (this._allDone(submissionId))
                this._onJourneyComplete(submissionId);
            return [];
        }

        var started = [];
        for (var i = 0; i < next.length; i++) {
            if (this._activate(next[i].module, submissionId, next[i].order))
                started.push(next[i].module);
        }

        gs.info(this.LOG + 'advance after ' + completedModuleCode + ' on ' + submissionId
            + ' started: ' + (started.join(', ') || 'nothing'));
        return started;
    },

    /**
     * An update arrived for a submission already in flight. Delegates to the
     * plan: either the same record is bumped and its cases restarted per the
     * restart columns, or a whole new submission version is cut and kicked off.
     *
     * @return { mode: 'override'|'new_version', submission: <sys_id> }
     */
    onUpdate: function (submissionId) {
        var result = this.plan.applyResubmit(submissionId);

        if (result.mode === Constants.CHOICE.SUBMISSION_UPDATE_MODE.NEW_VERSION
            && result.submission) {
            this.kickoff(result.submission);
        }
        return result;
    },

    /**
     * Clearance failed / submission declined: cancel every module case that
     * has not completed - record AND playbook.
     */
    cancelRemaining: function (submissionId) {
        var mods = this.plan._modules();
        var cancelled = 0;

        for (var i = 0; i < mods.length; i++) {
            var m = mods[i];
            if (!m.table)
                continue;
            var gr = new GlideRecord(m.table);
            if (!gr.isValid())
                continue;
            gr.addQuery('submission', submissionId);
            gr.addQuery('state', 'NOT IN', this.STATE.complete + ',' + this.STATE.cancelled);
            gr.query();
            while (gr.next()) {
                this.plan.cancelCase(gr, m, 'Submission journey cancelled');
                cancelled++;
            }
        }

        gs.info(this.LOG + 'cancelled ' + cancelled + ' open case(s) on ' + submissionId);
        return cancelled;
    },

    // Flip a dormant case to active, or create it if the plan changed since
    // kickoff and it was never made.
    _activate: function (moduleCode, submissionId, order) {
        var m = this.plan._moduleByCode(moduleCode);
        if (!m || !m.table)
            return false;

        var kase = this.plan.latestCase(m.table, submissionId);
        if (!kase) {
            var newId = this._createCase(moduleCode, submissionId, order, true);
            if (newId)
                this._startPlaybook(moduleCode, newId);
            return !!newId;
        }

        var state = String(kase.getValue('state') || '');
        if (state !== this.STATE.inactive)
            return false;   // already active, complete or cancelled

        kase.setValue('state', this.STATE.active);
        kase.setValue('is_active', true);
        kase.update();
        this._startPlaybook(moduleCode, kase.getUniqueValue());
        return true;
    },

    _createCase: function (moduleCode, submissionId, order, active) {
        var m = this.plan._moduleByCode(moduleCode);
        if (!m || !m.table) {
            gs.error(this.LOG + 'no case table registered for module ' + moduleCode);
            return '';
        }

        var gr = new GlideRecord(m.table);
        if (!gr.isValid()) {
            gs.error(this.LOG + 'case table does not exist: ' + m.table);
            return '';
        }

        gr.initialize();
        gr.setValue('submission', submissionId);
        gr.setValue('stage', order);
        gr.setValue('state', active ? this.STATE.active : this.STATE.inactive);
        gr.setValue('is_active', !!active);
        if (gr.isValidField('version'))
            gr.setValue('version', 1);
        if (gr.isValidField('short_description'))
            gr.setValue('short_description', (m.label || m.code) + ' for submission');

        // Business rules are deliberately NOT suppressed: the case number is
        // generated by one.
        return gr.insert();
    },

    _startPlaybook: function (moduleCode, caseId) {
        var m = this.plan._moduleByCode(moduleCode);
        if (m)
            this.plan.triggerPlaybook(m, caseId);
    },

    // Every module in the resolved plan is complete or cancelled.
    _allDone: function (submissionId) {
        var groups = this.plan.groupsFor(submissionId);
        if (!groups.length)
            return false;
        for (var g = 0; g < groups.length; g++) {
            for (var i = 0; i < groups[g].modules.length; i++) {
                if (!this.plan._isDone(groups[g].modules[i].module, submissionId))
                    return false;
            }
        }
        return true;
    },

    /**
     * Last run group closed: the pre-binding journey is done.
     *
     * ASSUMPTION: this writes state = closed and clears active. The previous
     * implementation wrote state = 'quoted', which is NOT in the submission's
     * choice list any more, so that write silently did nothing. `status` is
     * deliberately left alone - bound / declined / rejected is a business
     * outcome, not an orchestration one.
     */
    _onJourneyComplete: function (submissionId) {
        var sub = new GlideRecord(Constants.TABLE.SUBMISSION);
        if (!sub.get(submissionId))
            return;
        sub.setValue('state', Constants.CHOICE.STATE.CLOSED);
        sub.setValue('active', false);
        sub.update();
        gs.info(this.LOG + 'journey complete for submission ' + sub.getValue('number'));
    },

    type: 'OrchestrationService'
};
